-- The refunds the venue made in its provider's dashboard, and when a dispute opened, closed and must
-- be answered (#222; D122 §8, decision log 5.1, 5.9). Generated by drizzle-kit, then edited by hand:
-- row-level security and the updated_at trigger of the new table are appended. No row is updated or
-- inserted here, so there is no backfill: a dispute read before this migration has no times, and the
-- screens word that case without them. Privileges come from src/table-access.ts.

CREATE TABLE "restro"."payment_refunds" (
	"id" text PRIMARY KEY NOT NULL,
	"tenant_id" text NOT NULL,
	"venue_id" text NOT NULL,
	"payment_id" text NOT NULL,
	"amount_minor" bigint NOT NULL,
	"seen_at" timestamp with time zone DEFAULT now() NOT NULL,
	"service_date" date NOT NULL,
	"failed_at" timestamp with time zone,
	"storno_at" timestamp with time zone,
	"storno_by" text,
	"source" text NOT NULL,
	"actor" text NOT NULL,
	"job_id" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "payment_refunds_tenant_id_id_unique" UNIQUE("tenant_id","id"),
	CONSTRAINT "payment_refunds_id_format" CHECK ("restro"."payment_refunds"."id" ~ '^rf_[0-9A-Za-z]+$'),
	CONSTRAINT "payment_refunds_amount" CHECK ("restro"."payment_refunds"."amount_minor" > 0),
	CONSTRAINT "payment_refunds_storno" CHECK (("restro"."payment_refunds"."storno_at" is null) = ("restro"."payment_refunds"."storno_by" is null) and ("restro"."payment_refunds"."storno_by" is null or "restro"."payment_refunds"."storno_by" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$')),
	CONSTRAINT "payment_refunds_source" CHECK ("restro"."payment_refunds"."source" in ('guest', 'staff', 'worker', 'provider', 'restro', 'pos')),
	CONSTRAINT "payment_refunds_actor" CHECK ("restro"."payment_refunds"."actor" ~ '^(system|guest|(user|staff|integration|operator):[A-Za-z0-9][A-Za-z0-9_.:-]{0,127})$'),
	CONSTRAINT "payment_refunds_job_id" CHECK ("restro"."payment_refunds"."job_id" ~ '^[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}$')
);
